import{_ as t,o as a,c as o,a5 as d}from"./chunks/framework.BfQ7H7Qx.js";const p=JSON.parse('{"title":"API & Gateway Contracts (docs/api/)","description":"","frontmatter":{},"headers":[],"relativePath":"api/README.md","filePath":"api/README.md"}'),c={name:"api/README.md"};function i(s,e,l,r,n,g){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="api-gateway-contracts-docs-api" tabindex="-1">API &amp; Gateway Contracts (<code>docs/api/</code>) <a class="header-anchor" href="#api-gateway-contracts-docs-api" aria-label="Permalink to &quot;API &amp; Gateway Contracts (`docs/api/`)&quot;">​</a></h1><p>&gt; Navigation: <a href="./../">← Knowledge Base Hub</a> · <a href="./../architecture/README.html">← System Architecture</a> · <a href="./../database/README.html">Database Design →</a> · <a href="./../ba/README.html">Business Analysis →</a></p><p>Authoritative HTTP/REST, WebSocket/STOMP, RS256 authentication, Redis rate-limiting, and OpenAPI 3.1 specifications across <code>brandhub-api-gateway</code> (<code>:8080</code>), <code>brandhub-business-service</code> (<code>:8081</code>), <code>brandhub-ai-service</code> (<code>:8082</code>), and <code>brandhub-publisher-service</code> (<code>:8083</code>).</p><hr><h2 id="_1-contract-catalog" tabindex="-1">1. Contract Catalog <a class="header-anchor" href="#_1-contract-catalog" aria-label="Permalink to &quot;1. Contract Catalog&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Document</th><th style="text-align:left;">Service(s)</th><th style="text-align:left;">Scope &amp; Code-Verified Highlights</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./business-service-endpoints.html">Business &amp; Publisher Endpoint Reference</a></td><td style="text-align:left;"><code>business-service</code> (<code>:8081</code>), <code>publisher-service</code> (<code>:8083</code>), <code>api-gateway</code> (<code>:8080</code>)</td><td style="text-align:left;"><strong>Complete production REST &amp; STOMP endpoint catalog</strong> extracted from all <code>120+</code> Spring controllers across the <strong>9 SRS Functional Domains (<code>141</code> FRs)</strong>, STOMP WebSockets (<code>/ws/tasks</code>, <code>/ws/chat</code>), S3 encrypted media streaming, and 4-platform social OAuth</td></tr><tr><td style="text-align:left;"><a href="./api-response-format.html">Standard API Response Format (<code>ApiResponse&lt;T&gt;</code>)</a></td><td style="text-align:left;">All HTTP services</td><td style="text-align:left;">Mandatory JSON response envelope (<code>success</code>, <code>data</code>, <code>error</code>, <code>meta</code>, <code>requestId</code>, <code>version: &quot;v1&quot;</code>, <code>timestamp</code>), HTTP status mapping (<code>204</code> prohibited), and <code>97</code>-code <code>SCREAMING_SNAKE_CASE</code> error catalog</td></tr><tr><td style="text-align:left;"><a href="./rs256-jwt-flow.html">RS256 JWT Authentication Flow</a></td><td style="text-align:left;"><code>api-gateway</code> ↔ <code>business-service</code></td><td style="text-align:left;">RSA-2048 private-key signing (<code>business-service</code>), public-key perimeter verification (<code>api-gateway</code>), <code>InboundSecurityWebFilter</code> header sanitization, <code>15m</code> access + <code>30d</code> HttpOnly refresh rotation, and Redis <code>jwt:blacklist:{jti}</code> revocation</td></tr><tr><td style="text-align:left;"><a href="./redis-rate-limiting-filter.html">Redis Rate Limiting Filter</a></td><td style="text-align:left;"><code>api-gateway</code> (<code>RateLimitGatewayFilterFactory</code>)</td><td style="text-align:left;">Reactive Lua <code>INCR</code> + <code>EXPIRE</code> sliding-minute limiter (`ratelimit:gateway:{userId</td></tr><tr><td style="text-align:left;"><a href="./openapi-spec-business-service.html">OpenAPI 3.1 Spec — <code>business-service</code></a></td><td style="text-align:left;"><code>business-service</code> (<code>SpringDoc 2.6</code>)</td><td style="text-align:left;">Swagger UI (<code>http://localhost:8081/swagger-ui.html</code>), <code>/v3/api-docs.yaml</code>, reusable DTO components, gateway correlation headers, and validation checklist</td></tr><tr><td style="text-align:left;"><a href="./openapi-spec-ai-service.html">OpenAPI 3.1 Spec — <code>ai-service</code></a></td><td style="text-align:left;"><code>ai-service</code> (<code>FastAPI</code>)</td><td style="text-align:left;">Complete internal OpenAPI contract (<code>http://localhost:8082/docs</code> in dev) covering all <strong>15 v1 routers + v2 commercial image + internal routers (<code>68</code> routes)</strong> protected by <code>X-Internal-Key</code></td></tr></tbody></table><hr><h2 id="_2-gateway-perimeter-routing-summary-application-yml" tabindex="-1">2. Gateway Perimeter Routing Summary (<code>application.yml</code>) <a class="header-anchor" href="#_2-gateway-perimeter-routing-summary-application-yml" aria-label="Permalink to &quot;2. Gateway Perimeter Routing Summary (`application.yml`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Traffic Class</th><th style="text-align:left;">Gateway Route Predicate(s)</th><th style="text-align:left;">Auth &amp; Filter Chain</th><th style="text-align:left;">Downstream Target</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Authenticated Domain API</strong></td><td style="text-align:left;"><code>/api/v1/**</code> <em>(excluding public/webhook paths below)</em></td><td style="text-align:left;"><code>RequestIdWebFilter</code> → <code>InboundSecurityWebFilter</code> → <code>JwtAuthFilter</code> → <code>RateLimit</code> (<code>userId</code>)</td><td style="text-align:left;"><code>business-service:8081</code></td></tr><tr><td style="text-align:left;"><strong>Public Auth &amp; Google OAuth</strong></td><td style="text-align:left;"><code>/api/v1/auth/**</code>, <code>/login/oauth2/code/google</code></td><td style="text-align:left;">Public (<code>Guest</code>), auth rate limit</td><td style="text-align:left;"><code>business-service:8081</code></td></tr><tr><td style="text-align:left;"><strong>Public Guest Links</strong></td><td style="text-align:left;"><code>/api/v1/public/{mail,surveys,billing/plans,media-packages,images}/**</code></td><td style="text-align:left;">Public (<code>Guest</code>), IP-scoped <code>RateLimit</code> (<code>publicIp</code> / <code>publicPackageIp</code>)</td><td style="text-align:left;"><code>business-service:8081</code></td></tr><tr><td style="text-align:left;"><strong>Encrypted Repository Media</strong></td><td style="text-align:left;"><code>/api/v1/repository-media</code>, <code>/api/v1/repository-drive/media</code></td><td style="text-align:left;">Short-lived <code>AES-256-GCM</code> capability token + <code>capabilityIp</code> <code>RateLimit</code></td><td style="text-align:left;"><code>business-service:8081</code></td></tr><tr><td style="text-align:left;"><strong>SePay (VietQR) Webhook</strong></td><td style="text-align:left;"><code>POST /api/v1/billing/webhooks/sepay</code></td><td style="text-align:left;">Provider API key / signature check in <code>BillingController</code></td><td style="text-align:left;"><code>business-service:8081</code></td></tr><tr><td style="text-align:left;"><strong>4-Platform Social OAuth</strong></td><td style="text-align:left;"><code>GET /api/v1/social/{facebook,instagram,tiktok,threads}/{authorize,callback}</code></td><td style="text-align:left;">Single-use <code>60s</code> connect ticket + <code>bh_oauth_state</code> cookie + IP <code>RateLimit</code></td><td style="text-align:left;"><code>publisher-service:8083</code></td></tr><tr><td style="text-align:left;"><strong>STOMP WebSockets</strong></td><td style="text-align:left;"><code>/ws/tasks/**</code>, <code>/ws/chat/**</code></td><td style="text-align:left;"><code>WsJwtHandshakeInterceptor</code> / STOMP <code>CONNECT</code> JWT verification (<code>16 KB</code> frame cap)</td><td style="text-align:left;"><code>ws://business-service:8081</code></td></tr><tr><td style="text-align:left;"><strong>System Monitoring</strong></td><td style="text-align:left;"><code>/api/monitoring/{heartbeat,collectors/heartbeat,health-results,register,install.sh,agent.py}</code> (machine) &amp; <code>/api/monitoring/{enrollments,servers,health-targets}</code> (<code>Admin</code> JWT)</td><td style="text-align:left;">Machine token or <code>JwtAuthFilter</code> + <code>Admin</code> check</td><td style="text-align:left;"><code>business-service:8081</code></td></tr></tbody></table><hr><h2 id="_3-related-inter-service-specifications" tabindex="-1">3. Related Inter-Service Specifications <a class="header-anchor" href="#_3-related-inter-service-specifications" aria-label="Permalink to &quot;3. Related Inter-Service Specifications&quot;">​</a></h2><ul><li><a href="./../architecture/business-ai-rest-contract.html"><code>business-service</code> ↔ <code>ai-service</code> Internal REST Contract</a></li><li><a href="/brandhub-infrastructure/view.html?file=architecture/rabbitmq-publisher-contract.html"><code>business-service</code> ↔ <code>publisher-service</code> RabbitMQ Contract</a></li><li><a href="./../database/redis-cache/redis-key-patterns.html">Redis Key Patterns (<code>DA-E06-06</code>)</a></li></ul>',12)])])}const u=t(c,[["render",i]]);export{p as __pageData,u as default};
